def wording(text):
    for old,new in REPLACE.items():text=text.replace(old,new)
    # Keep code, formulas and API identifiers byte-for-byte intact.
    def plain(part):
        part=re.sub(r'\s*,?\s*как было сказано в S[1-7]\s*:',':',part)
        part=re.sub(r'\b(?:из|в|про|для) S[1-7](?:/S[1-7])?(?::\d+[–—-]\d+)?\b','',part)
        part=re.sub(r'\bS[1-7](?:/S[1-7])?(?::\d+[–—-]\d+)?\b','',part)
        return part.replace('В чатах','При выборе метода').replace('Вопрос чата','Вопрос').replace('в исходном чате','при обсуждении примера').replace('в чате','в примере')
    parts=re.split(r'(```[\s\S]*?```|\$\$[\s\S]*?\$\$|\$[^$\n]+\$|`[^`\n]+`)',text)
    text=''.join(p if i%2 else plain(p) for i,p in enumerate(parts))
    text=re.sub(r'<!-- source-depth-[^>]+-->','',text)
    return text

def main():
    cov=load();course=json.loads((ROOT/'course.json').read_text(encoding='utf8'))
    for c in course['chapters']:
        path=ROOT/c['path'];before=path.read_text(encoding='utf8')
        if wording(before)==before:continue
        transform(c['path'],wording,'Ссылка на контекст чата заменена самостоятельной постановкой вопроса; вычисления и оговорки сохранены. Требуется чтение изменённых формулировок.',cov)
        save(cov)
if __name__=='__main__':main()
